node --input-type=module <<'JS'
import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {parse} from 'smol-toml';import {createHash} from 'node:crypto';
const backup='.dip-local/rollback-20261029';const m=JSON.parse(fs.readFileSync(path.join(backup,'manifest.json')));
const saved=p=>fs.readFileSync(path.join(backup,m.settings.find(s=>s.source===p).backup),'utf8');
const c='/Users/itayzrihan/.codex/config.toml';const before=parse(saved(c)),after=parse(fs.readFileSync(c,'utf8'));
const originalDip=before.mcp_servers.dip;const currentDip=after.mcp_servers.dip;delete before.mcp_servers.dip;delete after.mcp_servers.dip;
assert.deepEqual(after,before,'Unrelated Codex configuration changed');
const h='/Users/itayzrihan/.codex/hooks.json';const hooksSame=saved(h)===fs.readFileSync(h,'utf8');
assert.deepEqual(JSON.parse(saved(h)),JSON.parse(fs.readFileSync(h,'utf8')),'Hook definitions changed');
const install=JSON.parse(fs.readFileSync('/Users/itayzrihan/.dip/install.json'));assert.equal(install.workflow,'automatic');
console.log(JSON.stringify({workflow:install.workflow,codexOtherSettingsPreserved:true,codexHooksByteIdentical:hooksSame,mcpDefinitionUnchanged:JSON.stringify(originalDip)===JSON.stringify(currentDip)}));
for(const f of ['src/automatic.js','src/actions.js','src/core.js','src/automation.js','public/app.js'])assert.equal(createHash('sha256').update(fs.readFileSync(f)).digest('hex'),createHash('sha256').update(fs.readFileSync(path.join('/opt/homebrew/lib/node_modules/@vxu-labs/dip',f))).digest('hex'));
console.log('Installed product files match validated candidate.');
